create or replace function pipeline.svc_pilot_submit_nonce(p_function text,p_body jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path to 'pipeline','net','public','extensions' as $function$ declare v_nonce uuid:=extensions.gen_random_uuid(); v_id bigint; begin if p_function not in ('layer1-ca-niagara-catalogue','qilt-au-etl') then raise exception 'one-time Pilot Edge function is not allowlisted'; end if; insert into pipeline.pilot_edge_nonces(id,function_name,expires_at) values(v_nonce,p_function,now()+interval '2 minutes'); select net.http_post(url:='https://fxcwkweaxjtknorudmwp.supabase.co/functions/v1/'||p_function,headers:=jsonb_build_object('content-type','application/json','x-cf-run-nonce',v_nonce::text),body:=coalesce(p_body,'{}'::jsonb),timeout_milliseconds:=120000) into v_id; return v_id; end $function$;
